from pathlib import Path
import base64,gzip,json,hashlib,subprocess

PAYLOAD=""
ops=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
p=Path('index.html')
data=p.read_bytes()
old_blob=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
if old_blob!='ea5c1d04be39532bae23b796b3040f76db3e2206':
    raise SystemExit('baseline git blob mismatch: '+old_blob)
src=data.splitlines(keepends=True)
out=[]; cursor=1
for n,o in enumerate(ops,1):
    i1,i2=int(o['i1']),int(o['i2'])
    if i1<cursor: raise SystemExit(f'overlap at op {n}')
    out.extend(src[cursor-1:i1-1])
    old=base64.b64decode(o.get('old_b64',''))
    new=base64.b64decode(o.get('new_b64',''))
    if o['tag']!='insert':
        actual=b''.join(src[i1-1:i2])
        if actual!=old: raise SystemExit(f'baseline mismatch at op {n}')
        cursor=i2+1
    else:
        if i2!=i1-1 or old: raise SystemExit(f'invalid insert op {n}')
        cursor=i1
    out.append(new)
out.extend(src[cursor-1:])
newdata=b''.join(out)
if len(newdata)!=4449842: raise SystemExit(f'output byte length mismatch: {len(newdata)}')
if hashlib.sha256(newdata).hexdigest()!='3a536b9439bc220f7485f407774dba569066a1878808267ba194bb35cbd58bee':
    raise SystemExit('output sha256 mismatch')
new_blob=hashlib.sha1(b'blob '+str(len(newdata)).encode()+b'\0'+newdata).hexdigest()
if new_blob!='badedd89d19714bc5db9105588cdd5b36365dcb5':
    raise SystemExit('output git blob mismatch: '+new_blob)
p.write_bytes(newdata)
subprocess.run(['git','rm','-f','.github/v1337_apply.py'],check=True)
print('v1337 exact manifest applied',new_blob)
